import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

// Logs every incoming request. No `matcher` is exported, so this runs on all
// requests, including static assets and _next internals.
export function proxy(request: NextRequest) {
  console.log(
    `[${new Date().toISOString()}] ${request.method} ${request.nextUrl.pathname}${request.nextUrl.search}`
  )
  return NextResponse.next()
}

